// utils/colors.js
export const generateUniqueColor = (key) => {
  // Simple deterministic hash
  let hash = 0;
  for (let i = 0; i < key.length; i++) {
    hash = key.charCodeAt(i) + ((hash << 5) - hash);
  }

  // Create hue from hash
  const hue = hash % 360;

  // Convert HSL -> HEX manually
  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    const k = n => (n + h / 30) % 12;
    const a = s * Math.min(l, 1 - l);
    const f = n =>
      l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));
    return (
      "#" +
      [f(0), f(8), f(4)]
        .map(x =>
          Math.round(x * 255)
            .toString(16)
            .padStart(2, "0")
        )
        .join("")
    );
  }

  return hslToHex(hue, 75, 50); // <-- returns valid hex string like "#e63946"
};
